const API_BASE_URL = 'http://localhost:8080/api';

export const AUTH_TOKEN_KEY = 'filia-auth-token';
export const AUTH_REFRESH_TOKEN_KEY = 'filia-auth-refresh-token';

const parseJsonSafe = async (response) => {
  try {
    return await response.json();
  } catch (error) {
    return null;
  }
};

const extractErrorMessage = (payload, fallbackMessage) => {
  if (!payload) return fallbackMessage;
  if (typeof payload.message === 'string' && payload.message.trim()) return payload.message;
  if (typeof payload.error === 'string' && payload.error.trim()) return payload.error;
  if (typeof payload.data === 'string' && payload.data.trim()) return payload.data;
  return fallbackMessage;
};

const postJson = async (path, body, token) => {
  const response = await fetch(`${API_BASE_URL}${path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {})
    },
    body: JSON.stringify(body)
  });

  const payload = await parseJsonSafe(response);

  if (!response.ok) {
    throw new Error(extractErrorMessage(payload, 'Заявката не беше успешна.'));
  }

  return payload;
};

export const storeSession = ({ token, refreshToken }) => {
  window.localStorage.setItem(AUTH_TOKEN_KEY, token);
  window.localStorage.setItem(AUTH_REFRESH_TOKEN_KEY, refreshToken);
};

export const clearSession = () => {
  window.localStorage.removeItem(AUTH_TOKEN_KEY);
  window.localStorage.removeItem(AUTH_REFRESH_TOKEN_KEY);
};

export const getStoredToken = () => window.localStorage.getItem(AUTH_TOKEN_KEY);

export const getStoredRefreshToken = () => window.localStorage.getItem(AUTH_REFRESH_TOKEN_KEY);

export const loginUser = async ({ email, password }) => {
  const loginPayload = await postJson('/auth/login', { email, password });
  const refreshToken = loginPayload?.refresh_token;

  if (!refreshToken) {
    throw new Error('Липсва refresh token от login отговора.');
  }

  const refreshed = await postJson('/auth/refresh', { refresh_token: refreshToken });

  if (!refreshed?.token || !refreshed?.refresh_token) {
    throw new Error('Липсват auth токени след refresh.');
  }

  storeSession({ token: refreshed.token, refreshToken: refreshed.refresh_token });
  return refreshed;
};

export const registerUser = async ({ email, fullName, password, repeatedPassword }) => {
  const registerPayload = await postJson('/auth/register', {
    email,
    full_name: fullName,
    password,
    repeated_password: repeatedPassword
  });

  const refreshToken = registerPayload?.refresh_token;

  if (!refreshToken) {
    throw new Error('Липсва refresh token от register отговора.');
  }

  const refreshed = await postJson('/auth/refresh', { refresh_token: refreshToken });

  if (!refreshed?.token || !refreshed?.refresh_token) {
    throw new Error('Липсват auth токени след refresh.');
  }

  storeSession({ token: refreshed.token, refreshToken: refreshed.refresh_token });
  return refreshed;
};

export const logoutUser = async () => {
  const token = getStoredToken();

  try {
    await postJson('/auth/logout', {}, token || undefined);
  } catch (error) {
    // Ignore logout transport errors; local session still needs to be cleared.
  } finally {
    clearSession();
  }
};
